  function PKG_GET_NUM_PIP_STAGES (
    iterIndex : natural
    ) return natural;

  function PKG_IS_INNER_PIPELINED (
    iterIndex : natural
    ) return boolean;

  function PKG_IS_OUTER_PIPELINED (
    iterIndex : natural
